import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        StringBuilder oqim = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String xabar = in.next();
            oqim.append(xabar.length()).append(":").append(xabar);
        }
        System.out.println(oqim.toString());
    }
}

